macro_rules! deps {
    () => {
        GenericSequence!();
        MappedGenericSequence!();
        FallibleGenericSequence!();
        MappedSequence!();
        GenericArray!();
        Mapped!();
    };
}

macro_rules! FunctionalSequence {
    () => {
        deps!();
        # [doc = " Defines functional programming methods for generic sequences"] pub trait FunctionalSequence < T > : GenericSequence < T > { # [doc = " Maps a `GenericSequence` to another `GenericSequence`."] # [doc = ""] # [doc = " If the mapping function panics, any already initialized elements in the new sequence"] # [doc = " will be dropped, AND any unused elements in the source sequence will also be dropped."] # [inline (always)] fn map < U , F > (self , f : F) -> MappedSequence < Self , T , U > where Self : MappedGenericSequence < T , U > , F : FnMut (Self :: Item) -> U , { FromIterator :: from_iter (self . into_iter () . map (f)) } # [doc = " Tries to map a `GenericSequence` to another `GenericSequence`, returning a `Result`."] # [doc = ""] # [doc = " If the mapping function errors or panics, any already initialized elements in the new sequence"] # [doc = " will be dropped, AND any unused elements in the source sequence will also be dropped."] # [inline (always)] fn try_map < U , F , E > (self , f : F) -> Result < MappedSequence < Self , T , U > , E > where Self : MappedGenericSequence < T , U > , Mapped < Self , T , U > : FallibleGenericSequence < U > , F : FnMut (Self :: Item) -> Result < U , E > , { < Mapped < Self , T , U > as FallibleGenericSequence < U > > :: from_fallible_iter (self . into_iter () . map (f) ,) } # [doc = " Combines two `GenericSequence` instances and iterates through both of them,"] # [doc = " initializing a new `GenericSequence` with the result of the zipped mapping function."] # [doc = ""] # [doc = " If the mapping function panics, any already initialized elements in the new sequence"] # [doc = " will be dropped, AND any unused elements in the source sequences will also be dropped."] # [doc = ""] # [doc = " **WARNING**: If using the `alloc` crate feature, mixing stack-allocated"] # [doc = " `GenericArray<T, N>` and heap-allocated `Box<GenericArray<T, N>>` within [`zip`](FunctionalSequence::zip)"] # [doc = " should be done with care or avoided."] # [doc = ""] # [doc = " For copy-types, it could be easy to accidentally move the array"] # [doc = " out of the `Box` when zipping with a stack-allocated array, which could cause a stack-overflow"] # [doc = " if the array is sufficiently large. However, that being said, the second where clause"] # [doc = " ensuring they map to the same sequence type will catch common errors, such as:"] # [doc = ""] # [doc = " ```compile_fail"] # [doc = " # use generic_array::{*, functional::FunctionalSequence};"] # [doc = " # #[cfg(feature = \"alloc\")]"] # [doc = " fn test() {"] # [doc = "     let stack = arr![1, 2, 3, 4];"] # [doc = "     let heap = box_arr![5, 6, 7, 8];"] # [doc = "     let mixed = stack.zip(heap, |a, b| a + b);"] # [doc = "     //                --- ^^^^ expected struct `GenericArray`, found struct `Box`"] # [doc = " }"] # [doc = " # #[cfg(not(feature = \"alloc\"))]"] # [doc = " # compile_error!(\"requires alloc feature to test this properly\");"] # [doc = " ```"] # [inline (always)] fn zip < B , Rhs , U , F > (self , rhs : Rhs , f : F) -> MappedSequence < Self , T , U > where Self : MappedGenericSequence < T , U > , Rhs : MappedGenericSequence < B , U , Mapped = MappedSequence < Self , T , U > > , Rhs : GenericSequence < B , Length = Self :: Length > , F : FnMut (Self :: Item , Rhs :: Item) -> U , { rhs . inverted_zip2 (self , f) } # [doc = " Folds (or reduces) a sequence of data into a single value."] # [doc = ""] # [doc = " If the fold function panics, any unused elements will be dropped."] # [inline (always)] fn fold < U , F > (self , init : U , f : F) -> U where F : FnMut (U , Self :: Item) -> U , { self . into_iter () . fold (init , f) } # [doc = " Folds (or reduces) a sequence of data into a single value, returning a `Result`."] # [doc = ""] # [doc = " If the fold function errors or panics, any unused elements will be dropped."] # [inline (always)] fn try_fold < U , E , F > (self , init : U , f : F) -> Result < U , E > where F : FnMut (U , Self :: Item) -> Result < U , E > , { self . into_iter () . try_fold (init , f) } }
    };
}

FunctionalSequence!()